           private void SetFlower() {
           	MemoryStream ms = new MemoryStream();
           	Image flower = pictureBox1.Image;
           	flower.Save(ms, System.Drawing.Imaging.ImageFormat.Jpeg);
           	Bitmap bm = new Bitmap(ms);
           	colorGrid1.Bitmap = bm;
           }

