override protected void OnInit(EventArgs e)
{

  ((Steema.TeeChart.Tools.Hotspot)(WebChart1.Chart.Tools[0])).GetHTMLMap += 
  new Steema.TeeChart.Tools.SeriesHotspotEventHandler(hotspot2_GetHTMLMap);

